export function FishLogo({
  size = 20,
  className,
  ...props
}: SVGProps<SVGSVGElement> & { size?: number }) {
  const height = Math.round((size * 17.04) / 23.16 * 10) / 10
  return (
    <svg
      width={size}
      height={height}
      viewBox="0 0 23.16 17.04"
      fill="currentColor"
      className={className}
      aria-hidden="true"
      {...props}
    >
      <path d={FISH_LOGO_PATH} />
    </svg>
  )
}

